<?php
require_once dirname(__DIR__) . '/middleware/bootstrap.php';
require_role('admin');
$db=Database::connection();$id=(int)($_GET['id']??0);$stmt=$db->prepare('SELECT s.*,u.email FROM students s JOIN users u ON u.id=s.user_id WHERE s.id=?');$stmt->execute([$id]);$student=$stmt->fetch();if(!$student){http_response_code(404);exit('Student not found.');}
$departments=$db->query('SELECT id,name FROM departments ORDER BY name')->fetchAll();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$name=post_string('full_name',160);$reg=strtoupper(post_string('register_number',40));$semester=(int)($_POST['semester']??0);$year=post_string('academic_year',20);$dept=(int)($_POST['department_id']??0);if(strlen($name)<2||strlen($reg)<3||$semester<1||$semester>12||!preg_match('/^\d{4}-\d{4}$/',$year))throw new DomainException('Enter a valid name, register number, semester, and academic year (YYYY-YYYY).');$stmt=$db->prepare('UPDATE students SET full_name=?,register_number=?,semester=?,academic_year=?,department_id=? WHERE id=?');$stmt->execute([$name,$reg,$semester,$year,$dept,$id]);$db->prepare('INSERT INTO audit_logs(actor_user_id,action,entity_type,entity_id,ip_address) VALUES(?,?,?,?,?)')->execute([current_user_id(),'student_profile_updated','student',$id,$_SERVER['REMOTE_ADDR']??null]);flash('success','Student profile updated.');redirect('admin/students.php');}catch(Throwable $e){$error=$e instanceof DomainException?$e->getMessage():($e instanceof PDOException&&(string)$e->getCode()==='23000'?'Register number already exists.':'Student profile could not be updated.');}}
page_start('Edit student','admin/students.php');
?>
<div class="content-width"><?php page_title('Edit student profile',$student['register_number'].' · '.$student['email']); ?><div class="panel"><div class="col-lg-7"><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><form method="post"><?= csrf_field() ?><div class="mb-3"><label class="form-label">Full name</label><input class="form-control" name="full_name" required value="<?= e($student['full_name']) ?>"></div><div class="mb-3"><label class="form-label">Register number</label><input class="form-control" name="register_number" required value="<?= e($student['register_number']) ?>"></div><div class="mb-3"><label class="form-label">Department</label><select class="form-select" name="department_id"><?php foreach($departments as $d): ?><option value="<?= (int)$d['id'] ?>" <?= (int)$student['department_id']===(int)$d['id']?'selected':'' ?>><?= e($d['name']) ?></option><?php endforeach; ?></select></div><div class="row g-3"><div class="col"><label class="form-label">Semester</label><input class="form-control" type="number" min="1" max="12" name="semester" value="<?= (int)$student['semester'] ?>"></div><div class="col"><label class="form-label">Academic year</label><input class="form-control" name="academic_year" value="<?= e($student['academic_year']) ?>"></div></div><button class="btn btn-primary mt-4">Save changes</button> <a class="btn btn-light mt-4" href="<?= e(url('admin/students.php')) ?>">Cancel</a></form></div></div></div>
<?php page_end(); ?>
